def bucketsort(arr, k):
    counts = [0] * k
    for x in arr:
        counts[x] += 1

    sorted_arr = []
    for i, count in enumerate(counts):
        sorted_arr.extend([i] * count)

    return sorted_arr

def find_first_in_sorted(arr, x):
    lo = 0
    hi = len(arr) - 1

    while lo <= hi:
        mid = (lo + hi) // 2

        if x == arr[mid] and (mid == 0 or x != arr[mid - 1]):
            return mid

        elif x <= arr[mid]:
            hi = mid - 1

        else:
            lo = mid + 1

    return -1

def flatten(arr):
    result = []
    for x in arr:
        if isinstance(x, list):
            for y in flatten(x):
                result.append(y)
        else:
            result.append(x)
    return result

def gcd(a, b):
    if b == 0:
        return a
    else:
        return gcd(b, a % b)

def is_valid_parenthesization(parens):
    depth = 0
    for paren in parens:
        if paren == '(':
            depth += 1
        else:
            depth -= 1
            if depth < 0:
                return False

    return depth == 0

def kheapsort(arr, k):
    import heapq

    heap = arr[:k]
    heapq.heapify(heap)

    for x in arr[k:]:
        heapq.heappush(heap, x)
        yield heapq.heappop(heap)

    while heap:
        yield heapq.heappop(heap)

def kth(arr, k):
    if len(arr) == 0:
        return None
    pivot = arr[0]
    below = [x for x in arr if x < pivot]
    above = [x for x in arr if x > pivot]

    num_less = len(below)
    num_lessoreq = len(arr) - len(above)

    if k < num_less:
        return kth(below, k) if below else None
    elif k >= num_lessoreq:
        return kth(above, k - num_lessoreq) if above else None
    else:
        return pivot

def lcs_length(s, t):
    from collections import Counter

    dp = Counter()

    for i in range(len(s)):
        for j in range(len(t)):
            if s[i] == t[j]:
                dp[(i, j)] = dp[(i - 1, j - 1)] + 1

    return max(dp.values()) if dp else 0

