def max_sublist_sum(arr):
    if not arr:
        return 0
    max_ending_here = arr[0]
    max_so_far = max(arr[0], 0)

    for x in arr[1:]:
        max_ending_here = max(max_ending_here + x, x)
        max_so_far = max(max_so_far, max_ending_here)

    return max_so_far

def mergesort(arr):
    def merge(left, right):
        result = []
        i = 0
        j = 0
        while i < len(left) and j < len(right):
            if left[i] <= right[j]:
                result.append(left[i])
                i += 1
            else:
                result.append(right[j])
                j += 1
        result.extend(left[i:] or right[j:])
        return result

    if len(arr) <= 1:
        return arr
    else:
        middle = len(arr) // 2
        left = mergesort(arr[:middle])
        right = mergesort(arr[middle:])
        return merge(left, right)

def next_permutation(perm):
    for i in range(len(perm) - 2, -1, -1):
        if perm[i] < perm[i + 1]:
            for j in range(len(perm) - 1, i, -1):
                if perm[j] > perm[i]:
                    next_perm = list(perm)
                    next_perm[i], next_perm[j] = perm[j], perm[i]
                    next_perm[i + 1:] = reversed(next_perm[i + 1:])
                    return next_perm
    return None

def pascal(n):
    rows = [[1]]
    for r in range(1, n):
        row = []
        for c in range(0, r + 1):
            upleft = rows[r - 1][c - 1] if c > 0 else 0
            upright = rows[r - 1][c] if c < len(rows[r-1]) else 0
            row.append(upleft + upright)
        rows.append(row)
    return rows

def possible_change(coins, total):
    if total == 0:
        return 1
    if total < 0:
        return 0

    if not coins:
        return 0

    first, *rest = coins
    return possible_change(coins, total - first) + possible_change(rest, total)

def powerset(arr):
    if arr:
        first, *rest = arr
        rest_subsets = powerset(rest)
        return [subset for subset in rest_subsets] + [[first] + subset for subset in rest_subsets]
    else:
        return [[]]

def rpn_eval(tokens):
    def op(symbol, a, b):
        return {
            '+': lambda a, b: a + b,
            '-': lambda a, b: a - b,
            '*': lambda a, b: a * b,
            '/': lambda a, b: a / b
        }[symbol](a, b)

    stack = []

    for token in tokens:
        if isinstance(token, float):
            stack.append(token)
        else:
            b = stack.pop()
            a = stack.pop()
            stack.append(
                op(token, a, b)
            )

    return stack.pop()

def sieve(max):
    primes = []
    for n in range(2, max + 1):
        if all(n % p != 0 for p in primes):
            primes.append(n)
    return primes

def wrap(text, cols):
    lines = []
    while len(text) > cols:
        end = text.rfind(' ', 0, cols + 1)
        if end == -1:
            end = cols
        line, text = text[:end], text[end:]
        lines.append(line)
    if len(text) > 0:
        lines.append(text)
    return lines
